17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Objects;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        if (isDuplicateOwner(owner)) {
106	            return new ResponseEntity<>(HttpStatus.CONFLICT);
107	        }
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    /**
116	     * Determines whether an owner already exists that shares the same last name and
117	     * telephone number as the given one.
118	     */
119	    private boolean isDuplicateOwner(Owner owner) {
120	        return this.clinicService.findOwnerByLastName(owner.getLastName()).stream()
121	            .anyMatch(existing ->
122	                Objects.equals(existing.getLastName(), owner.getLastName())
123	                    && Objects.equals(existing.getTelephone(), owner.getTelephone()));
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
129	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
130	        if (currentOwner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        currentOwner.setAddress(ownerFieldsDto.getAddress());
134	        currentOwner.setCity(ownerFieldsDto.getCity());
135	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
136	        currentOwner.setLastName(ownerFieldsDto.getLastName());
137	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
138	        this.clinicService.saveOwner(currentOwner);
139	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Transactional
144	    @Override
145	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        this.clinicService.deleteOwner(owner);
151	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        HttpHeaders headers = new HttpHeaders();
162	        Pet pet = petMapper.toPet(petFieldsDto);
163	        owner.setId(ownerId);
164	        pet.setOwner(owner);
165	        pet.getType().setName(null);
166	        this.clinicService.savePet(pet);
167	        PetDto petDto = petMapper.toPetDto(pet);
168	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
169	            .buildAndExpand(pet.getId()).toUri());
170	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner != null) {
178	            Pet currentPet = this.clinicService.findPetById(petId);
179	            if (currentPet != null) {
180	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
181	                currentPet.setName(petFieldsDto.getName());
182	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
183	                this.clinicService.savePet(currentPet);
184	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
185	            }
186	        }
187	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
193	        HttpHeaders headers = new HttpHeaders();
194	        Visit visit = visitMapper.toVisit(visitFieldsDto);
195	        Pet pet = new Pet();
196	        pet.setId(petId);
197	        visit.setPet(pet);
198	        this.clinicService.saveVisit(visit);
199	        VisitDto visitDto = visitMapper.toVisitDto(visit);
200	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
201	            .buildAndExpand(visit.getId()).toUri());
202	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
203	    }
204	
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
209	        Owner owner = this.clinicService.findOwnerById(ownerId);
210	        if (owner != null) {
211	            Pet pet = owner.getPet(petId);
212	            if (pet != null) {
213	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
214	            }
215	        }
216	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	    }
218	}
